import{_ as s,o as t,c as r,a2 as a}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Using Server Access","description":"The Server Access account page — requesting access, handling incoming requests, blocking users, and managing active grants.","frontmatter":{"title":"Using Server Access","description":"The Server Access account page — requesting access, handling incoming requests, blocking users, and managing active grants."},"headers":[],"relativePath":"ask-access/user-guide/server-access-page.md","filePath":"ask-access/user-guide/server-access-page.md","lastUpdated":1785513641000}'),n={name:"ask-access/user-guide/server-access-page.md"};function o(i,e,c,d,l,h){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="using-server-access" tabindex="-1">Using Server Access <a class="header-anchor" href="#using-server-access" aria-label="Permalink to &quot;Using Server Access&quot;">​</a></h1><p>Everything a user needs lives at <strong>Account → Server Access</strong> in the Pterodactyl client area. The page has three tabs — <strong>Received</strong>, <strong>Sent</strong>, and <strong>Active</strong> — plus request, preferences, and blocking panels on the left.</p><hr><h2 id="requesting-access" tabindex="-1">Requesting access <a class="header-anchor" href="#requesting-access" aria-label="Permalink to &quot;Requesting access&quot;">​</a></h2><p>Open <strong>Request Access</strong>, pick a request type, and send:</p><table tabindex="0"><thead><tr><th>Type</th><th>Identifier</th><th>What the owner approves</th></tr></thead><tbody><tr><td>A single server</td><td>Server ID — short ID (<code>1a2b3c4d</code>) or full UUID</td><td>Access to that one server</td></tr><tr><td>All servers of a user</td><td>The owner&#39;s account email</td><td>Access to <strong>every</strong> server they own</td></tr></tbody></table><p>Pick an <strong>access level</strong> (<code>Read-only</code>, <code>Standard</code>, <code>Full access</code>) and optionally add a short message (max 500 characters, HTML stripped). You can expand <em>&quot;Show what each access level includes&quot;</em> under <strong>My Preferences</strong> to see the exact permission list behind each level before asking.</p><div class="info custom-block"><p class="custom-block-title">Email requests are private by design</p><p>When you request by email, the response is identical whether or not that email has an account — so the feature can&#39;t be used to probe who&#39;s registered. If the account exists and accepts requests, your request lands in their <strong>Received</strong> tab; otherwise nothing happens.</p></div><p>While a request is pending you can <strong>Cancel</strong> it from the <strong>Sent</strong> tab. Handled requests (approved/denied/expired) can be removed from the list with <strong>Remove</strong>.</p><hr><h2 id="handling-incoming-requests" tabindex="-1">Handling incoming requests <a class="header-anchor" href="#handling-incoming-requests" aria-label="Permalink to &quot;Handling incoming requests&quot;">​</a></h2><p>The <strong>Received</strong> tab shows everyone asking for access to your servers. For each pending request you can:</p><ol><li><strong>Adjust the access level</strong> — override the preset the requester asked for.</li><li><strong>Choose a duration</strong> — <em>Permanent</em>, or temporary from 1 hour up to 30 days.</li><li><strong>Approve</strong> or <strong>Deny</strong>.</li></ol><p>Approving creates real Pterodactyl subusers — the requester sees the server(s) in their dashboard immediately. Temporary grants expire automatically: the subuser is removed and any live SFTP session is revoked within a minute of the deadline.</p><p>Approved requests show a <strong>Revoke access</strong> button for as long as the grant is live. Revoking deletes exactly the subusers that approval created — nothing else.</p><div class="tip custom-block"><p class="custom-block-title">Requests expire on their own</p><p>Pending requests decay after the admin-configured TTL (24 hours by default). You don&#39;t need to deny old requests — the scheduler marks them expired automatically.</p></div><hr><h2 id="the-active-tab" tabindex="-1">The Active tab <a class="header-anchor" href="#the-active-tab" aria-label="Permalink to &quot;The Active tab&quot;">​</a></h2><p><strong>Active</strong> is your fleet-wide access manager. It lists <strong>every subuser on every server you own or manage</strong>, grouped by user. For each person you can:</p><ul><li><strong>Edit permissions</strong> — click the ⚙ icon, toggle individual permissions grouped by category, and save. The full permission catalogue is shown with descriptions.</li><li><strong>Change duration</strong> — switch a grant between permanent and temporary, or extend/shorten temporary access.</li><li><strong>Add another server</strong> — use the <em>+ add server…</em> dropdown on their row to grant them access to more of your servers with the current preset.</li><li><strong>Remove access</strong> — the ✕ on a server chip revokes just that server; <em>Remove access</em> in the editor does the same.</li></ul><p>Rows tagged <strong>mgr</strong> hold the <code>accessmanager.manage</code> permission — those users can manage access on that server themselves from their own Server Access page. Rows tagged <strong>temp</strong> have a live expiry countdown.</p><hr><h2 id="my-preferences" tabindex="-1">My Preferences <a class="header-anchor" href="#my-preferences" aria-label="Permalink to &quot;My Preferences&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td>Accept incoming requests</td><td>When <strong>off</strong>, nobody can send you new requests (existing ones are unaffected).</td></tr><tr><td>Default access level offered</td><td>The preset pre-selected in your request form.</td></tr></tbody></table><hr><h2 id="blocking-users" tabindex="-1">Blocking users <a class="header-anchor" href="#blocking-users" aria-label="Permalink to &quot;Blocking users&quot;">​</a></h2><p>The <strong>Blocked Users</strong> panel stops specific accounts from ever requesting access to you:</p><ul><li>Add a block with the user&#39;s <strong>account email</strong>.</li><li>Blocking immediately <strong>auto-denies</strong> any pending requests from that user to you.</li><li>Blocked users get no error when they try — their requests are silently discarded, so they can&#39;t tell they&#39;ve been blocked.</li><li><strong>Unblock</strong> removes the block instantly.</li></ul><p>Blocks are rate-limited server-side (10 per minute by default) to prevent abuse.</p>',29)])])}const p=s(n,[["render",o]]);export{u as __pageData,p as default};
